cat >> src/boxOffice.test.ts <<'EOF'

// Test list:
// [ ] available returns capacity for a fresh section
// [ ] available: unknown section -> UNKNOWN_SECTION
// [ ] hold returns H1 with expiresAt and reduces availability
// [ ] hold ids increment; failed attempts don't use up a number
// [ ] hold validation: unknown section, invalid quantity, check order
// [ ] SOLD_OUT, no partial holds; taking exactly the rest works
// [ ] CUSTOMER_LIMIT across sections, counting holds and orders
// [ ] expired holds stop counting as soon as now >= expiresAt
// [ ] confirm creates O1, tickets stay taken
// [ ] confirm: unknown/confirmed/released -> UNKNOWN_HOLD, expired -> HOLD_EXPIRED
// [ ] pricing: Rappen rounding, group discount from 4 tickets, halves round up
// [ ] release frees tickets; errors; releasing an expired hold is a no-op
// [ ] cancelOrder refund (fee 200/ticket, min 0), frees tickets and limit; errors
// [ ] failed calls change nothing

function setup(overrides: Partial<BoxOfficeOptions> = {}) {
  const clock = { time: 1_000_000 };
  const office = createBoxOffice({
    sections: [
      { id: "PARKETT", capacity: 10, priceCents: 5000 },
      { id: "BALKON", capacity: 5, priceCents: 3000 },
    ],
    holdMinutes: 10,
    maxTicketsPerCustomer: 6,
    now: () => clock.time,
    ...overrides,
  });
  return { office, clock };
}

function expectCode(fn: () => unknown, code: BoxOfficeErrorCode) {
  let caught: unknown;
  try {
    fn();
  } catch (error) {
    caught = error;
  }
  expect(caught).toBeInstanceOf(BoxOfficeError);
  expect((caught as BoxOfficeError).code).toBe(code);
}

describe("available", () => {
  test("returns the capacity of a fresh section", () => {
    const { office } = setup();
    expect(office.available("PARKETT")).toBe(10);
    expect(office.available("BALKON")).toBe(5);
  });
});
EOF
sed -i 's|import { BoxOfficeError } from "./boxOffice";|import {\n  BoxOfficeError,\n  createBoxOffice,\n  type BoxOfficeErrorCode,\n  type BoxOfficeOptions,\n} from "./boxOffice";|' src/boxOffice.test.ts
bun test 2>&1 | tail -5

cat >> src/boxOffice.test.ts <<'EOF'

describe("confirm", () => {
  test("turns the hold into an order that keeps the tickets", () => {
    const { office, clock } = setup();
    const hold = office.hold("alice", "PARKETT", 3);
    expect(office.confirm(hold.holdId)).toEqual({
      orderId: "O1",
      customerId: "alice",
      sectionId: "PARKETT",
      quantity: 3,
      totalCents: 15000,
    });
    clock.time = hold.expiresAt + 1;
    expect(office.available("PARKETT")).toBe(7);
    expectCode(() => office.hold("alice", "BALKON", 4), "CUSTOMER_LIMIT");
  });

  test("numbers orders in creation order", () => {
    const { office } = setup();
    const first = office.hold("alice", "PARKETT", 1);
    const second = office.hold("bob", "PARKETT", 1);
    expect(office.confirm(second.holdId).orderId).toBe("O1");
    expect(office.confirm(first.holdId).orderId).toBe("O2");
  });
});
EOF
bun test 2>&1 | grep -E "^\(fail\)|pass$|fail$"
